import redis, sys, time, json

o_global = redis.Redis(port=6379, decode_responses=False)
n_global = redis.Redis(port=6380, decode_responses=False)
problems = []
total = 0

def eq(a, b, what):
    if a != b:
        problems.append(f"{what}: {a!r} != {b!r}")
        return False
    return True

TYPE_CHECKS = 0
def compare_value(t, o, n, key, ctx):
    global TYPE_CHECKS
    if t == b'string':
        eq(o.get(key), n.get(key), f"{ctx} GET")
    elif t == b'list':
        eq(o.lrange(key, 0, -1), n.lrange(key, 0, -1), f"{ctx} LRANGE")
    elif t == b'set':
        a, b = o.smembers(key), n.smembers(key)
        if a != b: problems.append(f"{ctx} SMEMBERS sets differ (sizes {len(a)}/{len(b)})")
    elif t == b'hash':
        a, b = o.hgetall(key), n.hgetall(key)
        if a != b: problems.append(f"{ctx} HGETALL differ (sizes {len(a)}/{len(b)})")
    elif t == b'zset':
        a = dict(o.zrange(key, 0, -1, withscores=True)); b = dict(n.zrange(key, 0, -1, withscores=True))
        if a != b: problems.append(f"{ctx} ZRANGE differ (sizes {len(a)}/{len(b)})")
        eq(o.zcard(key), n.zcard(key), f"{ctx} ZCARD")
    elif t == b'stream':
        compare_stream(o, n, key, ctx)
    else:
        problems.append(f"{ctx} UNHANDLED TYPE {t}")
    TYPE_CHECKS += 1

def compare_stream(o, n, key, ctx):
    # entries
    a, b = o.xrange(key, min='-', max='+'), n.xrange(key, min='-', max='+')
    if a != b:
        problems.append(f"{ctx} XRANGE entries differ ({len(a)} vs {len(b)} entries)")
    # stream metadata
    for f in (b'length', b'last-generated-id', b'max-deleted-entry-id', b'entries-added', b'recorded-first-entry-id'):
        xo, xn = o.xinfo_stream(key), n.xinfo_stream(key)
        eq(xo.get(f), xn.get(f), f"{ctx} XINFO_STREAM {f.decode()}")
    # groups
    go = {g[b'name']: g for g in o.xinfo_groups(key)}
    gn = {g[b'name']: g for g in n.xinfo_groups(key)}
    eq(sorted(go), sorted(gn), f"{ctx} group names")
    for gname in go:
        if gname not in gn: continue
        for f in (b'last-delivered-id', b'pending', b'consumers', b'entries-read', b'lag'):
            eq(go[gname].get(f), gn[gname].get(f), f"{ctx} group {gname.decode()} {f.decode()}")
        # consumers
        co = sorted([(c[b'name'], c[b'pending']) for c in o.xinfo_consumers(key, gname)])
        cn = sorted([(c[b'name'], c[b'pending']) for c in n.xinfo_consumers(key, gname)])
        eq(co, cn, f"{ctx} group {gname.decode()} consumers(name,pending)")
        # PEL: id, consumer, delivery count must match exactly; delivery time is absolute
        # internally - check via relative idle against wall clock gap
        t0 = time.time(); po = o.xpending(key, gname, min='-', max='+', count=1000000); t1 = time.time()
        pn = n.xpending(key, gname, min='-', max='+', count=1000000); t2 = time.time()
        eq(len(po), len(pn), f"{ctx} group {gname.decode()} PEL size")
        for eo, en in zip(po, pn):
            eq(eo[b'message_id'], en[b'message_id'], f"{ctx} group {gname.decode()} PEL id")
            eq(eo[b'consumer'], en[b'consumer'], f"{ctx} group {gname.decode()} PEL consumer")
            eq(eo[b'times_delivered'], en[b'times_delivered'], f"{ctx} group {gname.decode()} PEL delivery-count")

# ---- run over all dbs ----
old_keysets, new_keysets = {}, {}
for db in range(16):
    o = redis.Redis(port=6379, db=db, decode_responses=False)
    n = redis.Redis(port=6380, db=db, decode_responses=False)
    ok, nk = set(o.scan_iter(count=1000)), set(n.scan_iter(count=1000))
    old_keysets[db], new_keysets[db] = ok, nk
    if ok != nk:
        problems.append(f"db{db}: KEY SETS DIFFER: old-only={sorted(map(bytes.decode, ok-nk))[:10]} new-only={sorted(map(bytes.decode, nk-ok))[:10]}")
    for key in sorted(ok):
        total += 1
        ctx = f"db{db} {key.decode()}"
        t = o.type(key)
        eq(t, n.type(key), f"{ctx} TYPE")
        compare_value(t, o, n, key, ctx)
        # absolute expiry must match exactly
        eq(o.pexpiretime(key), n.pexpiretime(key), f"{ctx} PEXPIRETIME")

print(f"total keys compared: {total}")
print(f"type-aware comparisons run: {TYPE_CHECKS}")
if problems:
    print(f"PROBLEMS: {len(problems)}")
    for p in problems[:40]: print(" -", p)
    sys.exit(1)
print("RESULT: EXACT MATCH — key sets, types, absolute expiries, values, and stream group/consumer/PEL state")
